import{_ as a,c as i,o as l,ag as s}from"./chunks/framework.BtwP-r-R.js";const p=JSON.parse('{"title":"Conventions pour les identificateurs en C#","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"convention.md","filePath":"convention.md"}'),t={name:"convention.md"};function r(n,e,o,c,u,d){return l(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="conventions-pour-les-identificateurs-en-c" tabindex="-1">Conventions pour les identificateurs en C# <a class="header-anchor" href="#conventions-pour-les-identificateurs-en-c" aria-label="Permalink to &quot;Conventions pour les identificateurs en C#&quot;">​</a></h1><p>Dans tous les cas un identificateur doit être significatif dans le contexte où il est utilisé. Pour le reste, les identificateurs se différencient par leur casse, c&#39;est-à-dire, la combinaison de lettres majuscules et minuscules qui les composent. Deux conventions sont utilisées.</p><h2 id="casse-pascal-uppercamelcase" tabindex="-1">Casse Pascal (UpperCamelCase) <a class="header-anchor" href="#casse-pascal-uppercamelcase" aria-label="Permalink to &quot;Casse Pascal (UpperCamelCase)&quot;">​</a></h2><p>La première lettre de l&#39;identificateur et la première lettre de chaque mot concaténé suivant sont en majuscules. Vous pouvez utiliser la casse Pascal pour les identificateurs comportant trois caractères ou plus.<br> Par exemple :</p><ul><li>NbPointsDeVie</li><li>Solde</li><li>CalculerSalaireHebdomadaire(...)</li></ul><h2 id="casse-mixte-lowercamelcase" tabindex="-1">Casse mixte (lowerCamelCase) <a class="header-anchor" href="#casse-mixte-lowercamelcase" aria-label="Permalink to &quot;Casse mixte (lowerCamelCase)&quot;">​</a></h2><p>La première lettre de l&#39;identificateur est en minuscule et la première lettre de chaque mot concaténé suivant est en majuscules.<br> Par exemple :</p><ul><li>nomFamille</li><li>type</li><li>couleurDeRemplissage</li></ul><h2 id="casse-en-majuscule-avec-trait-de-soulignement" tabindex="-1">Casse en majuscule avec trait de soulignement <a class="header-anchor" href="#casse-en-majuscule-avec-trait-de-soulignement" aria-label="Permalink to &quot;Casse en majuscule avec trait de soulignement&quot;">​</a></h2><p>Toutes les lettes sont en majuscule et les mots sont séparés par un trait de soulignement (_). Exemple :</p><ul><li>NB_CARACTERES_MAX</li></ul><div class="warning custom-block"><p class="custom-block-title">Notes particulières pour tous les identifiants</p><ul><li>Les accents sont retirés des identificateurs.</li><li>Les identificateurs sont accordés</li><li>Exemples : <ul><li>NbPoutinesMangees</li></ul></li></ul></div><h2 id="identificateur-avec-le-casse-pascal-uppercamelcase" tabindex="-1">Identificateur avec le casse Pascal (UpperCamelCase) <a class="header-anchor" href="#identificateur-avec-le-casse-pascal-uppercamelcase" aria-label="Permalink to &quot;Identificateur avec le casse Pascal (UpperCamelCase)&quot;">​</a></h2><ul><li>Classe</li><li>Propriété (accesseurs get et set)</li><li>Fonction</li><li>Interface</li><li>Type enum <ul><li>Valeur d&#39;un type enum</li></ul></li><li>Espace de noms</li></ul><h2 id="identificateur-avec-le-casse-mixte-lowercamelcase" tabindex="-1">Identificateur avec le casse mixte (lowerCamelCase) <a class="header-anchor" href="#identificateur-avec-le-casse-mixte-lowercamelcase" aria-label="Permalink to &quot;Identificateur avec le casse mixte (lowerCamelCase)&quot;">​</a></h2><ul><li>Paramètre d&#39;une méthode</li><li>Attribut privé d&#39;une classe</li><li>Variable locale</li><li>Nom d’un contrôle graphique d’un formulaire.</li></ul><h3 id="cas-particulier" tabindex="-1">Cas particulier <a class="header-anchor" href="#cas-particulier" aria-label="Permalink to &quot;Cas particulier&quot;">​</a></h3><p>Pour les <strong>attributs privés d&#39;une classe</strong>, on utilise la case mixte tout en ajoutant le préfixe &quot;_&quot; à l&#39;identificateur.</p><p>Par exemple :</p><ul><li>_nbButs</li><li>_age</li><li>_prenom</li></ul><h2 id="identificateur-en-majuscule-et-trait-de-soulignement" tabindex="-1">Identificateur en majuscule et trait de soulignement <a class="header-anchor" href="#identificateur-en-majuscule-et-trait-de-soulignement" aria-label="Permalink to &quot;Identificateur en majuscule et trait de soulignement&quot;">​</a></h2><ul><li>Constante</li></ul><h2 id="ordre-des-elements-dans-une-classe" tabindex="-1">Ordre des éléments dans une classe <a class="header-anchor" href="#ordre-des-elements-dans-une-classe" aria-label="Permalink to &quot;Ordre des éléments dans une classe&quot;">​</a></h2><p>Lors de la création d&#39;une classe, les différents éléments devront <strong>toujours</strong> être dans cet ordre :</p><ul><li>constantes</li><li>attributs</li><li>propriétés</li><li>constructeur</li><li>méthodes</li></ul><h2 id="prefixe-pour-les-noms-des-controles-graphiques-des-formulaires" tabindex="-1">Préfixe pour les noms des contrôles graphiques des formulaires <a class="header-anchor" href="#prefixe-pour-les-noms-des-controles-graphiques-des-formulaires" aria-label="Permalink to &quot;Préfixe pour les noms des contrôles graphiques des formulaires&quot;">​</a></h2><ul><li>Label : lbl</li><li>Button : btn</li><li>TextBox : txt</li><li>RadioButton : opt</li><li>CheckBox : chk</li><li>ListBox : lst</li><li>ComboBox : cbo</li><li>GroupBox : gbo</li><li>PictureBox : pbo</li><li>Timer : tmr</li><li>StackPanel : spn</li><li>Image : img</li><li>Grid : grd</li><li>Panel : pnl</li><li>WrapPanel : wpn</li><li>ScrollBar : sbr</li><li>DatePicker : dtp</li><li>Form : frm (sdans le cas d&#39;un formulaire secondaire créé par notre code)</li></ul>',27)])])}const f=a(t,[["render",r]]);export{p as __pageData,f as default};
